import React,{useEffect,useMemo,useState} from 'react';
import {useNavigate} from 'react-router-dom';
import {useAuth} from '../context/AuthContext';
import {inventoryAPI} from '../services/api';
import SkinDetailModal from '../components/SkinDetailModal';
import ImageWithFallback from '../components/ImageWithFallback';
import { resolveItemImage } from '../utils/itemAssets';
const RARITIES=['Tous','Restricted','Classified','Covert','Contraband','Extraordinary'];
const CATEGORIES=['Toutes','AK','M4','AWP','Pistolets','knife','gloves'];
const rarityRank={'Mil-Spec':1,Restricted:2,Classified:3,Covert:4,Contraband:5,Extraordinary:6};
const categoryMatches=(c,f)=>f==='Toutes'||(f==='Pistolets'?['desert eagle','glock','usp'].some(x=>String(c).toLowerCase().includes(x)):String(c).toLowerCase()===f.toLowerCase());
export default function InventoryPage(){
 const {balance,updateBalance}=useAuth();const navigate=useNavigate();const[inventory,setInventory]=useState([]);const[loading,setLoading]=useState(true);const[selectedItem,setSelectedItem]=useState(null);const[sellingId,setSellingId]=useState(null);const[rarityFilter,setRarityFilter]=useState('Tous');const[categoryFilter,setCategoryFilter]=useState('Toutes');const[sortBy,setSortBy]=useState('value-desc');const[query,setQuery]=useState('');
 const load=async()=>{try{const r=await inventoryAPI.getInventory();setInventory(r.data||[])}catch(e){console.error(e)}finally{setLoading(false)}};useEffect(()=>{load()},[]);
 const displayed=useMemo(()=>inventory.filter(row=>{const i=row.item||{};return(!query.trim()||String(i.name||'').toLowerCase().includes(query.trim().toLowerCase()))&&(rarityFilter==='Tous'||i.rarity===rarityFilter)&&categoryMatches(i.category,categoryFilter)}).sort((a,b)=>{const ai=a.item||{},bi=b.item||{};if(sortBy==='value-asc')return Number(ai.virtual_value||0)-Number(bi.virtual_value||0);if(sortBy==='name')return String(ai.name||'').localeCompare(String(bi.name||''));if(sortBy==='rarity')return(rarityRank[bi.rarity]||0)-(rarityRank[ai.rarity]||0);if(sortBy==='quantity')return Number(b.quantity||0)-Number(a.quantity||0);return Number(bi.virtual_value||0)-Number(ai.virtual_value||0)}),[inventory,rarityFilter,categoryFilter,sortBy,query]);
 const sell=async row=>{if(sellingId)return;const i=row.item||{},amount=Number(i.virtual_value||0)*.75;setSellingId(row.id);try{const r=await inventoryAPI.sellItem(row.id);setInventory(cur=>cur.map(x=>x.id===row.id?{...x,quantity:Number(x.quantity)-1}:x).filter(x=>Number(x.quantity)>0));setSelectedItem(null);await updateBalance(r.data.balance_after)}catch(e){console.error(e)}finally{setSellingId(null)}};
 if(loading)return <div className="container"><div className="text-center py-5"><div className="spinner-border text-primary"/></div></div>;
 const totalValue=inventory.reduce((s,r)=>s+Number(r.item?.virtual_value||0)*Number(r.quantity||0),0);
 return <div className="container inventory-page-premium"><section className="inventory-hero"><div><span className="section-kicker">WELLCASE / ARMORY</span><h1>Ton <em>arsenal.</em></h1><p>Trie, inspecte, upgrade ou revends tes drops. Chaque skin compte dans ton duel 48H.</p></div><div className="inventory-summary"><span>VALEUR DE L'INVENTAIRE</span><strong>{totalValue.toLocaleString('fr-FR',{minimumFractionDigits:2})} €</strong><small>Liquidation à 75% : {(totalValue*.75).toLocaleString('fr-FR',{minimumFractionDigits:2})} €</small></div></section>
 <section className="inventory-toolbar"><div className="inventory-search"><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Rechercher une arme..."/></div><select value={sortBy} onChange={e=>setSortBy(e.target.value)}><option value="value-desc">Valeur ↓</option><option value="value-asc">Valeur ↑</option><option value="rarity">Rareté</option><option value="name">Nom</option><option value="quantity">Quantité</option></select></section>
 <div className="inventory-filter-block"><div><span>RARETÉ</span><div className="inventory-pills">{RARITIES.map(r=><button key={r} className={rarityFilter===r?'active':''} onClick={()=>setRarityFilter(r)}>{r}</button>)}</div></div><div><span>CATÉGORIE</span><div className="inventory-pills">{CATEGORIES.map(c=><button key={c} className={categoryFilter===c?'active':''} onClick={()=>setCategoryFilter(c)}>{c}</button>)}</div></div></div>
 <div className="inventory-result-line"><span>{displayed.length} type(s) affiché(s)</span><span>{Number(balance||0).toLocaleString('fr-FR')} € cash</span></div>
 <div className="inventory-grid-premium">{displayed.length?displayed.map(row=>{const i=row.item||{},sv=Number(i.virtual_value||0)*.75;return <article className="inventory-skin-card" key={row.id} onClick={()=>setSelectedItem(i)}><div className="inventory-skin-visual"><span className="inventory-rarity">{i.rarity}</span><ImageWithFallback src={resolveItemImage(i)} alt={i.name} className="inventory-skin-image"/></div><div className="inventory-skin-body"><span className="inventory-category">{i.category} · x{row.quantity}</span><h3>{i.name}</h3><div className="inventory-value-row"><strong>{Number(i.virtual_value||0).toLocaleString('fr-FR')} €</strong><span>vente {sv.toLocaleString('fr-FR',{minimumFractionDigits:2})} €</span></div><div className="inventory-actions"><button onClick={e=>{e.stopPropagation();setSelectedItem(i)}}>INSPECTER</button><button onClick={e=>{e.stopPropagation();sell(row)}} disabled={sellingId===row.id}>{sellingId===row.id?'VENTE…':'VENDRE 75%'}</button></div></div></article>}) : <div className="inventory-empty"><strong>Aucun skin ne correspond.</strong><span>Change tes filtres ou ouvre une caisse.</span></div>}</div>
 {selectedItem&&<SkinDetailModal skin={selectedItem} onClose={()=>setSelectedItem(null)} onUpgrade={()=>{setSelectedItem(null);navigate('/upgrade')}}/>}</div>
}
